#include <vector>
#include <algorithm>

class Solution {
public:
    int minDifficulty(std::vector<int>& jobDifficulty, int d) {
        int n = jobDifficulty.size();
        if (n < d) return -1;
        const int INF = 1e9;
        std::vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int day = 1; day <= d; ++day) {
            std::vector<int> nxt(n + 1, INF);
            for (int i = day; i <= n; ++i) {
                int curMax = 0;
                for (int j = i - 1; j >= day - 1; --j) {
                    curMax = std::max(curMax, jobDifficulty[j]);
                    if (dp[j] != INF) {
                        nxt[i] = std::min(nxt[i], dp[j] + curMax);
                    }
                }
            }
            dp = std::move(nxt);
        }
        return dp[n];
    }
};

import java.util.Arrays;

class Solution {
    public int minDifficulty(int[] jobDifficulty, int d) {
        int n = jobDifficulty.length;
        if (n < d) return -1;
        int INF = 1_000_000_000;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int day = 1; day <= d; day++) {
            int[] nxt = new int[n + 1];
            Arrays.fill(nxt, INF);
            for (int i = day; i <= n; i++) {
                int curMax = 0;
                for (int j = i - 1; j >= day - 1; j--) {
                    curMax = Math.max(curMax, jobDifficulty[j]);
                    if (dp[j] != INF) {
                        nxt[i] = Math.min(nxt[i], dp[j] + curMax);
                    }
                }
            }
            dp = nxt;
        }
        return dp[n];
    }
}

var minDifficulty = function(jobDifficulty, d) {
    const n = jobDifficulty.length;
    if (n < d) return -1;
    const INF = 1e9;
    let dp = new Int32Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let day = 1; day <= d; day++) {
        const nxt = new Int32Array(n + 1).fill(INF);
        for (let i = day; i <= n; i++) {
            let curMax = 0;
            for (let j = i - 1; j >= day - 1; j--) {
                if (jobDifficulty[j] > curMax) curMax = jobDifficulty[j];
                if (dp[j] !== INF) {
                    const cost = dp[j] + curMax;
                    if (cost < nxt[i]) nxt[i] = cost;
                }
            }
        }
        dp = nxt;
    }
    return dp[n];
};
